  if($action==='save_team_terms'){$poolId=(int)($_POST['pool_id']??0);agent_paid_appointments_save_team_terms_v800($pdo,$userId,$poolId,['payment_mode'=>(string)($_POST['payment_mode']??'free'),'price_cents'=>agent_commerce_decimal_to_minor_v800((string)($_POST['price']??'0')),'deposit_cents'=>agent_commerce_decimal_to_minor_v800((string)($_POST['deposit']??'0')),'currency'=>(string)($_POST['currency']??'usd'),'hold_minutes'=>(int)($_POST['hold_minutes']??30),'refund_before_hours'=>(int)($_POST['refund_before_hours']??24),'cancellation_fee_cents'=>agent_commerce_decimal_to_minor_v800((string)($_POST['cancellation_fee']??'0')),'cancellation_policy'=>(string)($_POST['cancellation_policy']??'')],$user);commerce_redirect_v800('Team appointment product saved.','team-pool-'.$poolId);}
