<section class="hero"><div><span class="eyebrow">Commerce + Paid Scheduling · Phase 8</span><h1>Sell products. Route fulfillment.</h1><p class="sub">VP3 subscription billing remains Stripe-only and separate. Commerce is the customer-payment layer: Product → Order → Payment → Fulfillment. Appointment is the first fulfillment adapter.</p></div><a class="btn" href="#orders">Orders</a></section>
<?php if($notice!==''):?><div class="notice ok" role="status"><?=e($notice)?></div><?php endif;?><?php if($error!==''):?><div class="notice err" role="alert"><?=e($error)?></div><?php endif;?>
<div class="grid"><section class="card" id="providers"><span class="eyebrow">Customer payment providers</span><h2>Connected providers</h2><p class="muted">Connect multiple personal/business merchant accounts. Products may use a fixed provider or customer choice; Team products always inherit the Team primary provider.</p><div class="providers"><?php foreach(['stripe','square'] as $provider):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="connect_provider"><input type="hidden" name="provider" value="<?=e($provider)?>"><button class="btn <?= $providerReady[$provider]?'primary':'' ?>" type="submit" <?=$providerReady[$provider]?'':'disabled'?>>Connect <?=e(agent_commerce_provider_label_v800($provider))?></button></form><?php endforeach;?><?php if($providerReady['paypal']):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="attach_paypal"><input name="merchant_id" maxlength="20" placeholder="PayPal Merchant ID" required><button class="btn primary" type="submit">Connect PayPal</button></form><?php else:?><span class="pill">PayPal not configured</span><?php endif;?></div><?php if(!$connections):?><div class="empty">No Commerce providers connected yet.</div><?php endif;?><?php foreach($connections as $c):?><div class="row"><div><strong><?=e(agent_commerce_provider_label_v800((string)$c['provider']))?></strong> <span class="pill <?= (string)$c['status']==='connected'?'good':'' ?>"><?=e((string)$c['status'])?></span><?php if(!empty($c['is_default_personal'])):?><span class="pill good">Personal default</span><?php endif;?><div class="muted"><?=e((string)($c['account_label']?:$c['external_account_id']))?></div></div><div class="actions"><?php if((string)$c['status']==='connected'&&!$c['is_default_personal']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="set_personal_default"><input type="hidden" name="connection_id" value="<?=(int)$c['id']?>"><button class="btn" type="submit">Make default</button></form><?php endif;?><?php if((string)$c['status']==='connected'):?><form method="post" onsubmit="return confirm('Disconnect this Commerce payment provider?')"><?=csrf_field()?><input type="hidden" name="action" value="disconnect_provider"><input type="hidden" name="connection_id" value="<?=(int)$c['id']?>"><button class="btn danger" type="submit">Disconnect</button></form><?php endif;?></div></div><?php endforeach;?></section>
<section class="card" id="team"><span class="eyebrow">Team commerce</span><h2>Team primary provider</h2><p class="muted">The canonical Team workspace owner is the Team Super Admin. Only that account can select or change the provider used by Team orders; assigned hosts inherit it.</p><?php if($connected):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="set_team_primary"><select name="connection_id" required><option value="">Select provider</option><?php foreach($connected as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($teamPrimary['connection_id']??0)===(int)$c['id'])?'selected':''?>><?=e(agent_commerce_provider_label_v800((string)$c['provider']).' · '.(string)($c['account_label']?:$c['external_account_id']))?></option><?php endforeach;?></select><button class="btn primary" type="submit">Save Team primary</button></form><?php else:?><div class="empty">Connect a provider before enabling paid Team products.</div><?php endif;?></section>
<section class="card" id="products"><span class="eyebrow">Canonical product catalog</span><h2>Products + fulfillment</h2><p class="muted">Phase 8 starts with appointment service products. These records are generic Commerce products; future fulfillment adapters can add digital goods, memberships, events, gifts, physical products, and mixed packages without changing payment lineage.</p><?php if(!$products):?><div class="empty">No Commerce products yet. Saving pricing on an appointment type creates its product record.</div><?php endif;?><?php foreach($products as $p):?><div class="row"><div><strong><?=e((string)$p['title'])?></strong> <span class="pill"><?=e((string)$p['product_type'])?></span> <span class="pill"><?=e((string)$p['fulfillment_type'])?> fulfillment</span><div class="muted">#<?=(int)$p['id']?> · <?=e((string)($p['binding_type']?:'unbound'))?> · <?=e(agent_commerce_money_v800((int)$p['price_cents'],(string)$p['currency']))?></div></div><span class="pill <?=!empty($p['is_active'])?'good':''?>"><?=!empty($p['is_active'])?'Active':'Inactive'?></span></div><?php endforeach;?></section>
